const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').split(/\s+/).filter(s => s.length > 0);
const n = parseInt(data[0], 10);
const a = [];
for (let i = 0; i < n; i++) a.push(parseInt(data[1 + i], 10));
a.sort((x, y) => x - y);

let count = 0;
// Para cada maior lado a[k] (array ordenado), conta pares (i, j) com i < j < k
// tais que a[i] + a[j] > a[k] (as outras desigualdades são automáticas).
// Two pointers: O(n^2) no total.
for (let k = n - 1; k >= 2; k--) {
  const ak = a[k];
  let i = 0, j = k - 1;
  while (i < j) {
    if (a[i] + a[j] > ak) {
      // a[i..j-1] + a[j] todos formam triângulo com a[k]
      count += j - i;
      j--;
    } else {
      i++;
    }
  }
}

console.log(count);
